() => {
  const buttons = Array.from(document.querySelectorAll('button'));
  const connectBtns = buttons.filter(b => b.textContent.includes('Connect'));
  let clicked = 0;
  for (const btn of connectBtns.slice(0, 25)) {
    try {
      btn.click();
      clicked++;
    } catch (e) {}
  }
  return `Clicked ${clicked} Connect buttons`;
}

