// This ensures the AI remembers what was summarized after compaction
if (result.summary) {
  const summaryMessage = {
    role: "system" as const,
    content: `CONVERSATION SUMMARY (compacted at ${new Date().toISOString()}): ${result.summary}`,
  };
  // Add summary at the beginning of remaining messages
  session.agent.addMessage(summaryMessage);
}

